using Microsoft.EntityFrameworkCore;

static async Task<Statement> BuildAsync(BankDb db, int accountId)
{
    // Default READ COMMITTED: each query sees the latest commits
    await using var tx = await db.Database.BeginTransactionAsync();
    var entries = db.Entries.Where(e => e.AccountId == accountId);
    var total = await entries.SumAsync(e => e.Amount);
    var lines = await entries.ToListAsync(); // T-SQL test: 750.00 vs 1,250.00
    return new Statement(total, lines);
}

using System.Data;
using Microsoft.EntityFrameworkCore;

static async Task<Statement> BuildAsync(BankDb db, int accountId)
{
    // One snapshot from the first read; needs ALLOW_SNAPSHOT_ISOLATION ON
    await using var tx =
        await db.Database.BeginTransactionAsync(IsolationLevel.Snapshot);
    var entries = db.Entries.Where(e => e.AccountId == accountId);
    var total = await entries.SumAsync(e => e.Amount);
    var lines = await entries.ToListAsync(); // T-SQL test: 750.00 and 750.00
    await tx.CommitAsync();
    return new Statement(total, lines);
}
